    m.Step(0.5f, false, 20.0f, false);
    ok = ok && m.Status == FC_STATUS_WAITING;
    c.ChallengeAccepted = true;
    m.Step(0.5f, false, 20.0f, false);
    ok = ok && m.Status == FC_STATUS_FIGHTING && c.Challenges == 1;
    m.Health = 10.0f;
